steps.action:
curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "{
      teams(filter: {name: {eq: \"Web\"}}) {
        nodes {
          id
          name
        }
      }
      users(filter: {name: {contains: \"Maya Chen\"}}) {
        nodes {
          id
          name
          email
        }
      }
    }"
  }'
